void page_fault_handler(uint32_t linear_addr, uint32_t error_code) {
    // 记录缺页线性地址
    write_cr2(linear_addr);

    // 根据错误码判断类型
    if (error_code & 0x1) {
        // 读取缺失
        load_page_from_disk(linear_addr);
    } else {
        // 写入缺失
        load_page_from_disk(linear_addr);
        mark_page_dirty(linear_addr);
    }

    // 重新执行原指令
    resume_instruction();
}

/* 图6.31所示页表示例 */
struct PageTableEntry {
    int page_frame;     // 物理页框号或磁盘地址
    int valid;          // 装入位：1=已调入主存，0=未调入
    int dirty;          // 修改位：1=已修改，0=未修改
    int accessed;       // 使用位：1=最近被访问
    int permissions;    // 访问权限：读/写/执行
    int no_cache;       // 禁止缓存位
};

// 示例：4个缓存页，2个未分配页，2个未缓存页
struct PageTableEntry page_table[8] = {
    {0, 1, 0, 1, 0b11, 0},  // VP1 -> PPO
    {1, 1, 0, 1, 0b11, 0},  // VP2 -> PP1
    {-1, 0, 0, 0, 0b00, 1}, // VP3 -> 未缓存，磁盘起始地址为-1
    {2, 0, 1, 1, 0b10, 0},  // VP4 -> 未分配
    {3, 1, 1, 0, 0b01, 1},  // VP5 -> PP3
    {4, 1, 0, 1, 0b11, 0},  // VP6 -> PP4
    {5, 0, 0, 0, 0b00, 1},  // VP7 -> 未缓存
    {-1, 0, 0, 0, 0b00, 1} // VPO -> 未分配
};
